        invariant |resultList| == |numbers| // resultList is always the same size as numbers
        invariant forall j :: 0 <= j < i ==> resultList[j] == Max(numbers[0..j+1]) // The rolling maximum is correctly maintained up to index i-1
    {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i];
        }
        resultList[i] := maxSoFar;
        i := i + 1;
